#!/usr/bin/env node
/**
 * build-icons — generate src/scripts/icons.js from the Material Symbols Rounded
 * SVGs (weight 400) in the @material-symbols/svg-400 devDependency.
 *
 * The app inlines icons (so they take `currentColor`, work offline, and cost no
 * extra request): every icon in ICONS gets its outline and filled path in the
 * generated file, and FP.icon('mic') returns the <svg>. To add an icon, add its
 * Material Symbol name below, run `npm run icons`, and commit src/scripts/icons.js.
 *
 * `filled: true` marks icons whose DEFAULT is the filled glyph (the design spec's
 * "Fill 1": stop, warning, achievement badges, attendance, lesson complete).
 * Pass { fill: true|false } to FP.icon to override per use (selected states).
 *
 *   node scripts/build-icons.mjs [--check]     --check fails if icons.js is stale
 */
import { readFileSync, writeFileSync, existsSync, copyFileSync, mkdirSync } from 'fs';
import { resolve } from 'path';

const ROOT = resolve(import.meta.dirname, '..');
const PKG = resolve(ROOT, 'node_modules/@material-symbols/svg-400');
const OUT = resolve(ROOT, 'src/scripts/icons.js');

// name → default fill. 51 design uses (icons-needed.md); `edit` and `description` are each used twice.
const ICONS = {
  // Student path
  mic: 0, stop: 1, pause: 0, volume_up: 0, menu_book: 0, edit: 0, record_voice_over: 0, headphones: 0,
  light_mode: 0, fitness_center: 0, checklist: 0, check: 0, warning: 1,
  keep: 0, // "Saved / resume" pin. The spec named push_pin, which is not in the package; `keep` is that pin glyph.
  sentiment_frustrated: 0, sentiment_neutral: 0, sentiment_satisfied: 0, sentiment_very_satisfied: 0,
  // Inline glyphs
  arrow_right_alt: 0, arrow_left_alt: 0, check_small: 0, close_small: 0,
  // Student extras
  videocam: 0, hourglass_top: 0, lightbulb: 0, target: 1, bar_chart: 1, description: 1,
  local_fire_department: 1, star: 1, school: 1, order_approve: 1,
  // Teacher
  group: 0, monitoring: 0, calendar_month: 0, assignment: 0, tune: 0, trending_up: 0, auto_stories: 0,
  person: 0, settings: 0, check_circle: 1, cancel: 1, mail: 0, save: 0, wand_stars: 0, recycling: 0,
  download_2: 0, upload_2: 0,
};

function pathOf(file) {
  const svg = readFileSync(file, 'utf-8');
  const ds = [...svg.matchAll(/<path d="([^"]+)"/g)].map((m) => m[1]);
  if (!ds.length) throw new Error('no <path> in ' + file);
  return ds.join(' ');
}

function build() {
  const entries = [];
  for (const [name, filled] of Object.entries(ICONS)) {
    const o = resolve(PKG, 'rounded', name + '.svg');
    const f = resolve(PKG, 'rounded', name + '-fill.svg');
    if (!existsSync(o) || !existsSync(f)) throw new Error(`Material Symbol "${name}" (outline + fill) not found in ${PKG}`);
    entries.push(`  ${name}: [${filled}, '${pathOf(o)}', '${pathOf(f)}']`);
  }
  return `/* ═══════════════════════════════════════════════════════════════
   FluentPath — Icons (GENERATED by scripts/build-icons.mjs — do not edit)
   Material Symbols Rounded, weight 400, Apache 2.0 (src/icons/LICENSE).
   FP.icon('mic')  → inline <svg class="fp-icon"> using currentColor.
   ═══════════════════════════════════════════════════════════════ */

var FP = window.FP || {};

/** name → [defaultFilled, outlinePath, filledPath] (viewBox 0 -960 960 960) */
FP.ICONS = {
${entries.join(',\n')}
};

/**
 * Inline SVG for a named icon.
 * @param {string} name   Material Symbol name, e.g. 'mic'
 * @param {object} [opts]
 * @param {boolean} [opts.fill]   force the filled (true) or outline (false) glyph
 * @param {string}  [opts.size]   'sm' (20px) | 'lg' (32px); default 24px
 * @param {string}  [opts.label]  accessible name; without it the icon is decorative (aria-hidden)
 * @param {string}  [opts.className] extra classes
 * Unknown names return '' (and warn) rather than throwing in the middle of a render.
 */
FP.icon = function (name, opts) {
  var def = FP.ICONS[name];
  if (!def) {
    if (typeof console !== 'undefined') console.warn('[FluentPath] Unknown icon: ' + name);
    return '';
  }
  opts = opts || {};
  var filled = opts.fill === undefined ? !!def[0] : !!opts.fill;
  var cls = 'fp-icon' + (opts.size ? ' fp-icon--' + opts.size : '') + (opts.className ? ' ' + opts.className : '');
  var a11y = opts.label
    ? 'role="img" aria-label="' + String(opts.label).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;') + '"'
    : 'aria-hidden="true" focusable="false"';
  return '<svg class="' + cls + '" viewBox="0 -960 960 960" ' + a11y + '><path d="' + (filled ? def[2] : def[1]) + '"/></svg>';
};

/**
 * Replace every <i data-icon="mic" data-icon-size="sm" data-icon-fill="true"
 * data-icon-label="Record"> placeholder under \`root\` with its SVG. Runs once on
 * DOMContentLoaded; call it again after inserting placeholders dynamically.
 */
FP.hydrateIcons = function (root) {
  (root || document).querySelectorAll('[data-icon]').forEach(function (el) {
    var fillAttr = el.getAttribute('data-icon-fill');
    var svg = FP.icon(el.getAttribute('data-icon'), {
      fill: fillAttr === null ? undefined : fillAttr !== 'false',
      size: el.getAttribute('data-icon-size') || undefined,
      label: el.getAttribute('data-icon-label') || undefined,
      className: el.getAttribute('data-icon-class') || undefined,
    });
    if (svg) el.outerHTML = svg;
  });
};
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function () { FP.hydrateIcons(); });
  else FP.hydrateIcons();
}
`;
}

const check = process.argv.includes('--check');
const next = build();
const license = resolve(ROOT, 'src/icons/LICENSE');
if (check) {
  if (!existsSync(OUT) || readFileSync(OUT, 'utf-8') !== next) {
    console.error('[build-icons] src/scripts/icons.js is stale. Run `npm run icons` and commit.');
    process.exit(1);
  }
  console.log('[build-icons] icons.js is current (' + Object.keys(ICONS).length + ' icons).');
} else {
  writeFileSync(OUT, next);
  mkdirSync(resolve(ROOT, 'src/icons'), { recursive: true });
  copyFileSync(resolve(PKG, 'LICENSE'), license);
  console.log('[build-icons] wrote src/scripts/icons.js (' + Object.keys(ICONS).length + ' icons, ' + Math.round(next.length / 1024) + ' KB) and src/icons/LICENSE');
}
